  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When you say \"total overtime hours per month for the entire workforce cannot exceed 20 hours per worker,\" do you mean each individual worker is capped at 20 overtime hours per month (so total workforce overtime is 20 × number of workers that month), or is there a single aggregate cap of 20 hours for the whole workforce combined?"
  ],
  "rationale": "The response asks for a single policy clarification regarding the interpretation of the overtime cap (per-worker vs. aggregate), which constitutes one semantically independent question."
}

